mapper.select:
SELECT order_id, user_id, merchant_id, status, total_amount, created_at, completed_at, failure_reason, version
FROM orders
WHERE order_id = #{orderId}

SELECT order_id, user_id, merchant_id, status, total_amount, created_at, completed_at, failure_reason, version
FROM orders
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{offset}, #{limit}

SELECT order_id, user_id, merchant_id, status, total_amount, created_at, completed_at, failure_reason, version
FROM orders
WHERE merchant_id = #{merchantId}
ORDER BY created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM orders
WHERE user_id = #{userId}

SELECT COUNT(*)
FROM orders
WHERE merchant_id = #{merchantId}

SELECT order_id, user_id, merchant_id, status, total_amount, created_at, completed_at, failure_reason, version
FROM orders
WHERE status = #{status, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
  AND created_at < #{timeoutThreshold}
ORDER BY created_at ASC
LIMIT #{limit}
